INSERT INTO "kjv" ("verseid","versenumber","chapternumber","book","verse") VALUES (3880,28,7,'Num','One kid of the goats for a sin offering:');
INSERT INTO "kjv" ("verseid","versenumber","chapternumber","book","verse") VALUES (3881,29,7,'Num','And for a sacrifice of peace offerings, two oxen, five rams, five he goats, five lambs of the first year: this was the offering of Eliab the son of Helon.');
INSERT INTO "kjv" ("verseid","versenumber","chapternumber","book","verse") VALUES (3882,30,7,'Num','On the fourth day Elizur the son of Shedeur, prince of the children of Reuben, did offer:');
